import React, {useRef,useState,useEffect} from "react";

import './ImageUpload.css';
import Button from "./Button";


const ImageUpload=props=>{

    const [file,setFile]=useState();
    const [previewUrl,setPreviewUrl]=useState();
    const [isValid,setIsValid]=useState(false);

    const filePickerRef=useRef();

    useEffect(()=>{
        //if its empty
        if(!file)
            return;

        const fileReader=new FileReader();
        fileReader.onload=()=>{
            setPreviewUrl(fileReader.result)
        }
        fileReader.readAsDataURL(file);

    },[file]);

    const pickedHandler = event =>{

        let pickedFile;
        let fileIsValid;
        //if we are getting a file into the props
        if(event.target.files&&event.target.files.length===1){
            pickedFile=event.target.files[0];
            setFile(pickedFile);
            setIsValid(true);
            fileIsValid=true;
        }
        //if no file added
        else{
            setIsValid(false);
            fileIsValid=false;
        }
        props.onInput(props.id,pickedFile,fileIsValid);
        
    };

    //must create a function to handle scene when we click on our button
    const pickImageHandler=()=>{
        filePickerRef.current.click();
    }
    return(//we create an input form which isnt visible which takes images
        <div className="form-control">
            <input
                id={props.id}
                ref={filePickerRef}
                style={{display: 'none'}}
                type="file"
                accept=".jpg,.png,.jpeg"
                onChange={pickedHandler}
            />
            {/*must create a button to access that form*/}
            <div className={`image-upload ${props.center && 'center'}`}>
                <div className="image-upload__preview">
                    {previewUrl&&<img src={previewUrl} alt="Preview"/>}
                    {!previewUrl&&<p>please pick an image</p>}
                </div>
                <Button type="button" onClick={pickImageHandler}>PICK IMAGE</Button>
            </div>
            {!isValid&&<p>{props.errorText}</p>}
        </div>
    );
};

export default ImageUpload;